def hand(site,tool='key_handle',food=0,force_ids=(),delta=(0,0,0),approach=(0,0,-1),jaw=(0,1,0),intended=()):
    p=[round(a+b,6) for a,b in zip(sites[site],delta)];t=tools[tool];nom=[];chk=[]
    for f in force_ids:
        # Force directions are explicitly overwritten for brushing/peeling below.
        nom.append([0,0,forces[f]['nominal_N']]);chk.append([0,0,forces[f]['design_N']])
    return dict(pos=p,frame='counter',approach=list(approach),jaw_axis=list(jaw),roll_deg=0,
        held=tool,held_kg=round(t['mass_kg']+food,4),work_offset_m=t['work_local_m'],mass_offset_m=t['com_local_m'],
        jaw_opening_m=.028,nominal_forces_N=nom or [[0,0,0]],check_forces_N=chk or [[0,0,0]],
        force_model_ids=list(force_ids),intended=list(intended),grip=t['grip'],work_site=site)
def segment(label,site,tool='key_handle',food=0,force_ids=(),contact=(),mode='approach',side='R'):
    d1=(0,0,.10);d2=(0,0,0)
    if mode=='lift':d1,d2=d2,d1
    if mode=='slide':d1,d2=(0,-.04,0),(0,.08,0)
    if mode=='sweep':d1,d2=(-.06,0,0),(.06,0,0)
    poses=[{side:hand(site,tool,food,force_ids,d,intended=contact)} for d in (d1,d2)]
    return dict(label=label,station=site,poses=poses,jaw_axes=[[0,1,0],[1,0,0]],interpolation='Cartesian straight line at<=.05 m/s, accel<=.3 m/s2',intended_contact_pairs=list(contact))
