geometry=[]
def box(name,center,size,group='environment',mount=False):geometry.append(dict(name=name,type='box',center_m=center,size_m=size,frame='counter',group=group,mount_contact=mount))
for a in layout:
    if a['id'].startswith('output_') or a['id']=='sink_insert':continue
    x,y=a['center_xy_m'];h=a['height_m'];sx,sy=a['full_footprint_m']
    if a['id']=='guarded_cutter':
        box('cell_base',[x,y,.018],[.48,.34,.012],'fixed_appliance_robot_part')
        for xx in [-.21,.21]:
            for yy in [-.13,.13]:box(f'cell_mount_{xx}_{yy}',[x+xx,y+yy,.006],[.028,.028,.012],'fixed_appliance_robot_part',True)
        box('cell_left_post',[x-.20,y+.02,.19],[.025,.025,.33],'fixed_appliance_robot_part')
        box('cell_right_post',[x+.20,y+.02,.19],[.025,.025,.33],'fixed_appliance_robot_part')
        box('cell_bridge',[x,y+.02,.355],[.425,.045,.04],'fixed_appliance_robot_part')
        box('cell_guard_back',[x,y+.16,.18],[.46,.004,.31],'fixed_appliance_robot_part')
        box('cell_guard_front',[x,y-.12,.18],[.46,.004,.31],'fixed_appliance_robot_part')
        for sign in [-1,1]:box('cell_guard_side'+str(sign),[x+sign*.23,y+.02,.18],[.004,.28,.31],'fixed_appliance_robot_part')
        box('covered_tool_support',[x,y-.09,.115],[.20,.16,.006])
    elif a['id']=='tool_dock':
        box('tool_dock_base',[x,y,.004],[sx,sy,.008])
        for j,yy in enumerate([.105,.30,.495]):box('tool_support_'+str(j),[x,yy,.045],[.16,.12,.010])
    else:
        box(a['id']+'_floor',[x,y,.004],[sx,sy,.008])
        for sign in [-1,1]:box(a['id']+'_side'+str(sign),[x+sign*(sx/2-.002),y,.04],[.004,sy,.08])
for food in ['carrot','potato','leafy_greens','tomato']:
    x,y=next(a['center_xy_m'] for a in layout if a['id']=='output_'+food)
    geometry.append(dict(name='output_'+food+'_bowl',type='cylinder_shell',center_m=[x,y,.045],radius_m=.10,height_m=.09,thickness_m=.001,frame='counter',group='environment_vessel'))
    box('output_'+food+'_key',[x,y,.18],[.06,.028,.02])
    for sign in [-1,1]:box('output_'+food+'_bail'+str(sign),[x+sign*.083,y,.12],[.012,.012,.15])
